public:
    vector<int> addToArrayForm(vector<int>& num, int k) {

        int n = num.size();
        int carry = 0;


        for(int i = n-1; i >= 0;i--){

            int sum = num[i] + (k % 10) + carry;
            k /= 10;
            carry = sum / 10;
            num[i] = sum % 10;

        }

        k += carry;

        while(k > 0){
            num.insert(num.begin(),k % 10);
            k /= 10;
        }

        return num;
    }
};

package task_989;

import java.math.BigDecimal;
import java.util.LinkedList;
import java.util.List;

/*
The array-form of an integer num is an array representing its digits in left to right order.

For example, for num = 1321, the array form is [1,3,2,1].
Given num, the array-form of an integer, and an integer k, return the array-form of the integer num + k.

Example 1:

Input: num = [1,2,0,0], k = 34
Output: [1,2,3,4]
Explanation: 1200 + 34 = 1234
Example 2:

Input: num = [2,7,4], k = 181
Output: [4,5,5]
Explanation: 274 + 181 = 455
 */
public class Task989 {
    public List<Integer> addToArrayForm(int[] num, int k) {
        StringBuilder stringBuilder = new StringBuilder();
        for (int i : num) {
            stringBuilder.append(i);
        }
        BigDecimal number = new BigDecimal(stringBuilder.toString());
        BigDecimal sum = number.add(new BigDecimal(k));
        String stringSum = String.valueOf(sum);
        System.out.println(stringSum);
        List<Integer> result = new LinkedList<>();
        for (int i = 0; i < stringSum.length(); i++) {
            result.add(Integer.valueOf(Character.toString(stringSum.charAt(i))));
        }
        return result;
    }

}

class Solution {
    public List<Integer> addToArrayForm(int[] A, int K) {
        int N = A.length;
        int cur = K;
        List<Integer> ans = new ArrayList();

        int i = N;
        while (--i >= 0 || cur > 0) {
            if (i >= 0)
                cur += A[i];
            ans.add(cur % 10);
            cur /= 10;
        }

        Collections.reverse(ans);
        return ans;
    }
}

class Solution(object):
    def addToArrayForm(self, A, K):
        A[-1] += K
        for i in xrange(len(A) - 1, -1, -1):
            carry, A[i] = divmod(A[i], 10)
            if i: A[i-1] += carry
        if carry:
            A = map(int, str(carry)) + A
        return A

